  const assignedIds = new Set(
    (map.paradigms || []).flatMap(p => p.observationIds || [])
  )

  const unassigned = allObs.filter(o =>
    !assignedIds.has(o.id) &&
    (filterTrack === 'all' || o.trackId === filterTrack)
  )

  function addParadigm() {
    if (!newParadigmLabel.trim()) return
    const paradigm = {
      id: uuidv4(),
      label: newParadigmLabel.trim(),
      color: PARADIGM_COLORS[colorIndex % PARADIGM_COLORS.length],
      note: '',
      observationIds: [],
    }
    const next = { ...map, paradigms: [...(map.paradigms || []), paradigm] }
    persist(next)
    setColorIndex(c => (c + 1) % PARADIGM_COLORS.length)
    setNewParadigmLabel('')
    setAddingParadigm(false)
  }

  function deleteParadigm(paradigmId) {
    if (!confirm('Delete this paradigm group? Observations will return to unassigned.')) return
    persist({ ...map, paradigms: map.paradigms.filter(p => p.id !== paradigmId) })
  }

