        <div className="flex-1">
          <h1 className="font-display text-xl text-ash">{map.title}</h1>
          {(map.venue || map.date) && (
            <p className="text-mist text-xs">{[map.venue, map.date].filter(Boolean).join(' · ')}</p>
          )}
