import { PARADIGM_COLORS } from '../utils/defaults.js'
import { exportMapAsPDF, exportMapAsImage } from '../utils/export.js'

function ObsCard({ obs, trackLabel, markerLabel, isDragging }) {
  return (
    <div
      className={`bg-flat rounded-lg p-3 text-xs border border-flat cursor-grab select-none transition-all ${
        isDragging ? 'opacity-40' : 'hover:border-ash/20'
      }`}
    >
      <p className="text-ash leading-relaxed mb-2">{obs.content}</p>
      <div className="flex gap-1 flex-wrap">
        {trackLabel && (
          <span className="text-void bg-mist/40 rounded px-1.5 py-0.5 text-[10px]">{trackLabel}</span>
        )}
        {markerLabel && (
          <span className="text-void bg-mist/30 rounded px-1.5 py-0.5 text-[10px]">{markerLabel}</span>
        )}
      </div>
    </div>
  )
}

function DroppableParadigm({ paradigm, observations, trackMap, markerMap, onRemove, onRename, onNoteChange, onDelete, activeId }) {
  const [editingName, setEditingName] = useState(false)
  const [nameDraft, setNameDraft] = useState(paradigm.label)
  const [editingNote, setEditingNote] = useState(false)
  const [noteDraft, setNoteDraft] = useState(paradigm.note || '')

  function commitName() {
    setEditingName(false)
    if (nameDraft.trim()) onRename(paradigm.id, nameDraft.trim())
  }

  function commitNote() {
    setEditingNote(false)
    onNoteChange(paradigm.id, noteDraft)
  }

  return (
    <div
      id={`paradigm-${paradigm.id}`}
      className="rounded-xl border-2 p-4 min-h-[160px] transition-colors"
      style={{ borderColor: paradigm.color + '66', backgroundColor: paradigm.color + '0a' }}
    >
      {/* Paradigm header */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex-1">
          {editingName ? (
            <input
              autoFocus
              value={nameDraft}
              onChange={e => setNameDraft(e.target.value)}
              onBlur={commitName}
              onKeyDown={e => { if (e.key === 'Enter') commitName() }}
              className="font-display text-base bg-transparent border-b w-full focus:outline-none"
              style={{ borderColor: paradigm.color, color: paradigm.color }}
            />
          ) : (
            <h3
              className="font-display text-base cursor-pointer hover:opacity-80"
              style={{ color: paradigm.color }}
              onClick={() => setEditingName(true)}
            >
              {paradigm.label}
            </h3>
          )}
          <span className="text-mist text-[10px]">{observations.length} observation{observations.length !== 1 ? 's' : ''}</span>
        </div>
        <button onClick={() => onDelete(paradigm.id)} className="text-mist/30 hover:text-red-400 text-xs ml-2 transition-colors">×</button>
      </div>

      {/* Note field */}
      <div className="mb-3">
        {editingNote ? (
          <textarea
            autoFocus
            value={noteDraft}
            onChange={e => setNoteDraft(e.target.value)}
            onBlur={commitNote}
            placeholder="Add an interpretive note…"
            className="w-full bg-void/50 rounded p-2 text-ash text-xs resize-none border-0 min-h-[60px] focus:outline-none"
          />
        ) : (
          <p
            className="text-mist/70 text-xs italic cursor-pointer hover:text-mist transition-colors min-h-[24px]"
            onClick={() => setEditingNote(true)}
          >
            {paradigm.note || 'Click to add interpretive note…'}
          </p>
        )}
      </div>

      {/* Observation cards in this paradigm */}
      <div className="space-y-2">
        {observations.map(obs => (
          <div key={obs.id} className="relative group">
            <ObsCard
              obs={obs}
              trackLabel={trackMap[obs.trackId]}
              markerLabel={markerMap[obs.timeMarkerId]}
              isDragging={obs.id === activeId}
            />
            <button
              onClick={() => onRemove(paradigm.id, obs.id)}
              className="absolute top-1 right-1 text-mist/30 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all text-xs"
            >
              ×
            </button>
          </div>
        ))}
        {observations.length === 0 && (
          <p className="text-mist/30 text-xs text-center py-4 border border-dashed rounded-lg"
             style={{ borderColor: paradigm.color + '30' }}>
            Drag observations here
          </p>
        )}
      </div>
    </div>
  )
}

