            className="border border-flat text-mist hover:text-ash hover:border-ash/30 px-3 py-1.5 rounded-lg text-xs transition-colors"
          >
            {copied ? 'Copied!' : 'Share Link'}
          </button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div id="paradigm-canvas" className="flex flex-1 overflow-hidden">
          {/* Left panel: unassigned observations */}
          <aside className="w-72 min-w-[18rem] border-r border-flat flex flex-col bg-stage overflow-hidden">
            <div className="px-4 py-3 border-b border-flat">
              <h2 className="font-display text-base text-ash">Observations</h2>
              <p className="text-mist text-xs mt-0.5">{unassigned.length} unassigned</p>
              {/* Filter by track */}
              {map.tracks.length > 0 && (
                <select
                  value={filterTrack}
                  onChange={e => setFilterTrack(e.target.value)}
                  className="mt-2 w-full bg-flat border border-flat rounded px-2 py-1 text-ash text-xs focus:outline-none"
                >
                  <option value="all">All tracks</option>
                  {map.tracks.filter(t => t.visible).map(t => (
                    <option key={t.id} value={t.id}>{t.label}</option>
                  ))}
                </select>
              )}
            </div>
            <div className="flex-1 overflow-y-auto p-3 space-y-2">
              {allObs.length === 0 && (
                <div className="text-center py-8">
                  <p className="text-mist text-xs">No observations yet.</p>
                  <Link to={`/map/${id}`} className="text-gold text-xs hover:underline">Go to Stage 1 to add some →</Link>
                </div>
              )}
              {unassigned.map(obs => (
                <DraggableCard
                  key={obs.id}
                  obs={obs}
                  trackLabel={trackMap[obs.trackId]}
                  markerLabel={markerMap[obs.timeMarkerId]}
                  isDragging={obs.id === activeId}
                />
              ))}
              {unassigned.length === 0 && allObs.length > 0 && (
                <p className="text-mist/50 text-xs text-center py-4">All observations assigned!</p>
              )}
            </div>
          </aside>

          {/* Right: paradigm groups */}
          <main className="flex-1 overflow-auto p-6">
            {/* Add paradigm */}
            <div className="mb-6">
              {addingParadigm ? (
                <div className="flex items-center gap-3">
                  <input
                    autoFocus
                    value={newParadigmLabel}
                    onChange={e => setNewParadigmLabel(e.target.value)}
                    onKeyDown={e => {
                      if (e.key === 'Enter') addParadigm()
                      if (e.key === 'Escape') { setAddingParadigm(false); setNewParadigmLabel('') }
                    }}
                    placeholder="Name this paradigm… e.g. Puppetry / mechanisation"
                    className="bg-flat border rounded px-3 py-2 text-ash text-sm w-80 focus:outline-none"
                    style={{ borderColor: PARADIGM_COLORS[colorIndex % PARADIGM_COLORS.length] }}
                  />
                  <button onClick={addParadigm} className="text-sm font-semibold px-4 py-2 rounded-lg transition-colors"
                    style={{ backgroundColor: PARADIGM_COLORS[colorIndex % PARADIGM_COLORS.length], color: '#0a0a14' }}>
                    Add
                  </button>
                  <button onClick={() => { setAddingParadigm(false); setNewParadigmLabel('') }} className="text-mist hover:text-ash text-sm transition-colors">Cancel</button>
                </div>
              ) : (
                <button
                  onClick={() => setAddingParadigm(true)}
                  className="border border-dashed border-violet/40 hover:border-violet text-violet/70 hover:text-violet px-5 py-2 rounded-lg text-sm transition-colors"
                >
                  + Add Paradigm Group
                </button>
              )}
            </div>

            {/* Paradigm groups grid */}
            {(map.paradigms || []).length === 0 && (
              <div className="text-center py-20">
                <p className="font-display text-xl text-mist mb-2">No paradigms yet</p>
                <p className="text-mist/50 text-sm max-w-sm mx-auto">
                  Add a paradigm group above, then drag observations from the left panel into it to build your interpretive clusters.
                </p>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4 xl:grid-cols-3">
              {(map.paradigms || []).map(paradigm => {
                const paradigmObs = (paradigm.observationIds || [])
                  .map(oid => Object.values(map.observations).find(o => o.id === oid))
                  .filter(Boolean)

                return (
                  <DroppableArea key={paradigm.id} id={`paradigm-${paradigm.id}`}>
                    <DroppableParadigm
                      paradigm={paradigm}
                      observations={paradigmObs}
                      trackMap={trackMap}
                      markerMap={markerMap}
                      onRemove={removeFromParadigm}
                      onRename={renameParadigm}
                      onNoteChange={updateParadigmNote}
                      onDelete={deleteParadigm}
                      activeId={activeId}
                    />
                  </DroppableArea>
                )
              })}
            </div>
          </main>
        </div>

        <DragOverlay>
          {activeObs ? (
            <div className="rotate-2 opacity-90">
              <ObsCard
                obs={activeObs}
                trackLabel={trackMap[activeObs.trackId]}
                markerLabel={markerMap[activeObs.timeMarkerId]}
              />
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </div>
  )
}

// Draggable card wrapper
import { useDraggable } from '@dnd-kit/core'
function DraggableCard({ obs, trackLabel, markerLabel, isDragging }) {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({ id: obs.id })
  const style = transform ? { transform: `translate(${transform.x}px, ${transform.y}px)` } : undefined

  return (
    <div ref={setNodeRef} style={style} {...listeners} {...attributes}>
      <ObsCard obs={obs} trackLabel={trackLabel} markerLabel={markerLabel} isDragging={isDragging} />
    </div>
  )
}

// Droppable area wrapper
import { useDroppable } from '@dnd-kit/core'
function DroppableArea({ id, children }) {
  const { setNodeRef, isOver } = useDroppable({ id })
  return (
    <div ref={setNodeRef} className={`transition-all ${isOver ? 'scale-[1.01]' : ''}`}>
      {children}
    </div>
  )
}

