import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { v4 as uuidv4 } from 'uuid'
import { loadMap, saveMap } from '../utils/storage.js'
import { DEFAULT_TRACK_DEFINITIONS } from '../utils/defaults.js'
import { exportMapAsPDF, exportMapAsImage } from '../utils/export.js'

// ── Inline observation cell for the full map view ──────────────────────────
function ObservationCell({ value, onChange, color }) {
  const [editing, setEditing] = useState(false)
  const [draft, setDraft] = useState(value || '')

  useEffect(() => { setDraft(value || '') }, [value])

  function commit() {
    setEditing(false)
    if (draft !== (value || '')) onChange(draft)
  }

  if (editing) {
    return (
      <textarea
        autoFocus
        value={draft}
        onChange={e => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={e => { if (e.key === 'Escape') { setDraft(value || ''); setEditing(false) } }}
        className="w-full h-full min-h-[80px] bg-void/80 text-ash text-xs p-2 resize-none border-0 rounded"
        style={{ borderTop: `2px solid ${color}` }}
      />
    )
  }

  return (
    <div
      onClick={() => setEditing(true)}
      className="min-h-[80px] p-2 cursor-text text-xs text-ash/80 hover:bg-flat/40 rounded transition-colors leading-relaxed"
      style={{ borderTop: `2px solid ${draft ? color : 'transparent'}` }}
    >
      {draft || <span className="text-mist/30">click to add note</span>}
    </div>
  )
}

// ── Guided mode panel ───────────────────────────────────────────────────────
function GuidedPanel({ track, trackIndex, totalTracks, timeMarkers, observations, onObservationChange, onNext, onPrev, onExit, onAddMarker }) {
  const [addingMarker, setAddingMarker] = useState(false)
  const [newMarkerLabel, setNewMarkerLabel] = useState('')
  const def = DEFAULT_TRACK_DEFINITIONS.find(d => d.schemaCategory === track.schemaCategory)
  const questions = def?.guidingQuestions || []

  function submitMarker() {
    if (!newMarkerLabel.trim()) return
    onAddMarker(newMarkerLabel.trim())
    setNewMarkerLabel('')
    setAddingMarker(false)
  }

  const obsForTrack = timeMarkers.map(m => {
    const key = `${track.id}:${m.id}`
    return { marker: m, key, value: observations[key]?.content || '' }
  })

  return (
    <div className="flex flex-col h-full">
      {/* Progress bar */}
      <div className="flex items-center gap-1 px-6 py-3 border-b border-flat bg-stage">
        {Array.from({ length: totalTracks }).map((_, i) => (
          <div
            key={i}
            className="h-1 flex-1 rounded-full transition-all"
            style={{ backgroundColor: i === trackIndex ? track.color : i < trackIndex ? track.color + '55' : '#2a2a40' }}
          />
        ))}
        <span className="text-mist text-xs ml-3 whitespace-nowrap">
          {trackIndex + 1} of {totalTracks}
        </span>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Left: element info + prompts */}
        <aside className="w-72 min-w-[18rem] border-r border-flat flex flex-col bg-stage overflow-y-auto">
          <div className="p-6">
            <div
              className="text-xs font-semibold uppercase tracking-widest mb-1"
              style={{ color: track.color }}
            >
              Element {trackIndex + 1}
            </div>
            <h2
              className="font-display text-2xl mb-4"
              style={{ color: track.color }}
            >
              {track.label}
            </h2>

            {questions.length > 0 && (
              <div className="space-y-3">
                <p className="text-mist text-xs uppercase tracking-widest">Guiding questions</p>
                {questions.map((q, i) => (
                  <div key={i} className="flex gap-2">
                    <span className="text-mist/40 text-xs mt-0.5 flex-shrink-0">—</span>
                    <p className="text-ash/70 text-sm leading-relaxed">{q}</p>
                  </div>
                ))}
              </div>
            )}

            <div className="mt-6 pt-6 border-t border-flat">
              <p className="text-mist/50 text-xs leading-relaxed italic">
                Add your observations in the columns to the right — one column per moment in the performance.
              </p>
            </div>
          </div>
        </aside>

        {/* Right: observation columns per time marker */}
        <main className="flex-1 overflow-x-auto overflow-y-auto">
          {timeMarkers.length === 0 ? (
            <div className="flex items-center justify-center h-full text-center px-8">
              <div>
                <p className="font-display text-xl text-mist mb-2">No time markers yet</p>
                <p className="text-mist/50 text-sm mb-5">
                  Add at least one time marker to start recording observations. These mark the moments or sections of the performance.
                </p>
                {addingMarker ? (
                  <div className="flex items-center gap-2 justify-center">
                    <input
                      autoFocus
                      value={newMarkerLabel}
                      onChange={e => setNewMarkerLabel(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter') submitMarker(); if (e.key === 'Escape') setAddingMarker(false) }}
                      placeholder="e.g. Pre-show, Act 1, Interval…"
                      className="bg-flat border border-gold/50 rounded px-3 py-2 text-ash text-sm w-56 focus:border-gold focus:outline-none"
                    />
                    <button onClick={submitMarker} className="bg-gold text-void font-semibold px-4 py-2 rounded-lg text-sm hover:bg-gold-dim transition-colors">Add</button>
                    <button onClick={() => setAddingMarker(false)} className="text-mist hover:text-ash text-sm">×</button>
                  </div>
                ) : (
                  <button
                    onClick={() => setAddingMarker(true)}
                    className="bg-gold text-void font-semibold px-5 py-2.5 rounded-lg hover:bg-gold-dim transition-colors"
                  >
                    + Add First Time Marker
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div className="flex h-full min-h-full p-4 gap-3 items-start">
              {obsForTrack.map(({ marker, key, value }) => (
                <GuidedCell
                  key={key}
                  marker={marker}
                  value={value}
                  color={track.color}
                  onChange={val => onObservationChange(track.id, marker.id, val)}
                />
              ))}
              {/* Add another time marker inline */}
              <div className="flex-shrink-0 pt-8">
                {addingMarker ? (
                  <div className="flex flex-col gap-2 w-44">
                    <input
                      autoFocus
                      value={newMarkerLabel}
                      onChange={e => setNewMarkerLabel(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter') submitMarker(); if (e.key === 'Escape') setAddingMarker(false) }}
                      placeholder="New marker…"
                      className="bg-flat border border-gold/50 rounded px-2 py-1.5 text-ash text-xs focus:border-gold focus:outline-none"
                    />
                    <div className="flex gap-2">
                      <button onClick={submitMarker} className="text-gold text-xs hover:text-gold-dim">Add</button>
                      <button onClick={() => setAddingMarker(false)} className="text-mist text-xs hover:text-ash">×</button>
                    </div>
                  </div>
                ) : (
                  <button
                    onClick={() => setAddingMarker(true)}
                    className="border border-dashed border-gold/30 hover:border-gold/60 text-gold/50 hover:text-gold rounded-xl px-4 py-3 text-xs transition-colors w-36 h-32 flex items-center justify-center"
                  >
                    + Add Time Marker
                  </button>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Navigation footer */}
      <div className="border-t border-flat px-6 py-4 bg-stage flex items-center justify-between">
        <button
          onClick={onExit}
          className="text-mist hover:text-ash text-sm transition-colors"
        >
          View full map
        </button>
        <div className="flex items-center gap-3">
          {trackIndex > 0 && (
            <button
              onClick={onPrev}
              className="border border-flat text-mist hover:text-ash hover:border-ash/30 px-4 py-2 rounded-lg text-sm transition-colors"
            >
              ← {trackIndex > 0 ? 'Previous' : ''}
            </button>
          )}
          {trackIndex < totalTracks - 1 ? (
            <button
              onClick={onNext}
              className="px-5 py-2 rounded-lg text-sm font-semibold transition-colors"
              style={{ backgroundColor: track.color, color: '#0a0a14' }}
            >
              Next element →
            </button>
          ) : (
            <button
              onClick={onExit}
              className="bg-gold text-void px-5 py-2 rounded-lg text-sm font-semibold hover:bg-gold-dim transition-colors"
            >
              Done — view map ✓
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

function GuidedCell({ marker, value, color, onChange }) {
  const [draft, setDraft] = useState(value || '')
  const timerRef = useRef(null)

  useEffect(() => { setDraft(value || '') }, [value])

  function handleChange(val) {
    setDraft(val)
    clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => onChange(val), 600)
  }

  return (
    <div className="flex-shrink-0 w-52 flex flex-col">
      <div
        className="text-sm font-medium mb-2 px-1 pb-2 border-b"
        style={{ color, borderColor: color + '44' }}
      >
        {marker.label}
      </div>
      <textarea
        value={draft}
        onChange={e => handleChange(e.target.value)}
        placeholder="Your observations…"
        className="flex-1 min-h-[240px] bg-flat/60 border border-flat rounded-xl p-3 text-ash text-sm resize-none focus:outline-none focus:border-opacity-60 leading-relaxed placeholder-mist/30 transition-colors"
        style={{ '--tw-border-opacity': 1 }}
        onFocus={e => e.target.style.borderColor = color + '88'}
        onBlur={e => { e.target.style.borderColor = ''; onChange(draft) }}
      />
    </div>
  )
}

// ── Main MapView ────────────────────────────────────────────────────────────
export default function MapView() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [map, setMap] = useState(null)
  const [copied, setCopied] = useState(false)
  const [showExport, setShowExport] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [editingTitle, setEditingTitle] = useState(false)
  const [titleDraft, setTitleDraft] = useState('')
  const [newMarkerLabel, setNewMarkerLabel] = useState('')
  const [addingMarker, setAddingMarker] = useState(false)
  const [newTrackLabel, setNewTrackLabel] = useState('')
  const [addingTrack, setAddingTrack] = useState(false)
  const [guidedMode, setGuidedMode] = useState(false)
  const [guidedTrackIndex, setGuidedTrackIndex] = useState(0)

  useEffect(() => {
    const m = loadMap(id)
    if (!m) { navigate('/'); return }
    setMap(m)
    setTitleDraft(m.title)
  }, [id])

  const persist = useCallback((updated) => {
    const saved = saveMap(updated)
    setMap(saved)
  }, [])

  if (!map) return null

  const visibleTracks = map.tracks
    .filter(t => t.visible)
    .sort((a, b) => a.order - b.order)

  function updateObservation(trackId, markerId, content) {
    const key = `${trackId}:${markerId}`
    const obs = { ...map.observations }
    if (content.trim()) {
      obs[key] = { id: obs[key]?.id || uuidv4(), trackId, timeMarkerId: markerId, content }
    } else {
      delete obs[key]
    }
    persist({ ...map, observations: obs })
  }

  function addTimeMarker(label) {
    const lbl = label || newMarkerLabel
    if (!lbl.trim()) return
    const marker = { id: uuidv4(), label: lbl.trim(), position: map.timeMarkers.length }
    persist({ ...map, timeMarkers: [...map.timeMarkers, marker] })
    setNewMarkerLabel('')
    setAddingMarker(false)
  }

  function deleteTimeMarker(markerId) {
    const obs = { ...map.observations }
    Object.keys(obs).forEach(k => { if (k.endsWith(`:${markerId}`)) delete obs[k] })
    persist({
      ...map,
      timeMarkers: map.timeMarkers.filter(m => m.id !== markerId),
      observations: obs,
    })
  }

  function addTrack() {
    if (!newTrackLabel.trim()) return
    const track = {
      id: uuidv4(),
      label: newTrackLabel.trim(),
      schemaCategory: null,
      color: '#8888aa',
      order: map.tracks.length,
      visible: true,
      isDefault: false,
    }
    persist({ ...map, tracks: [...map.tracks, track] })
    setNewTrackLabel('')
    setAddingTrack(false)
  }

  function toggleTrack(trackId) {
    persist({
      ...map,
      tracks: map.tracks.map(t => t.id === trackId ? { ...t, visible: !t.visible } : t),
    })
  }

  function commitTitle() {
    setEditingTitle(false)
    if (titleDraft.trim() && titleDraft !== map.title) {
      persist({ ...map, title: titleDraft.trim() })
    }
  }

  function copyLink() {
    navigator.clipboard.writeText(window.location.href)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  async function handleExport(type) {
    setExporting(true)
    setShowExport(false)
    const slug = map.title.toLowerCase().replace(/\s+/g, '-').slice(0, 40)
    if (type === 'pdf') await exportMapAsPDF('map-canvas', slug)
    else await exportMapAsImage('map-canvas', slug)
    setExporting(false)
  }

  function enterGuidedMode() {
    setGuidedTrackIndex(0)
    setGuidedMode(true)
  }

  const hiddenTracks = map.tracks.filter(t => !t.visible)
  const currentGuidedTrack = visibleTracks[guidedTrackIndex]

  return (
    <div className="min-h-screen bg-void flex flex-col">
      {/* Top bar */}
      <header className="border-b border-flat px-6 py-3 flex items-center gap-4 bg-stage sticky top-0 z-20">
        <Link to="/" className="text-mist hover:text-ash transition-colors text-sm">← Home</Link>
        <div className="flex-1">
          {editingTitle ? (
            <input
              autoFocus
              value={titleDraft}
              onChange={e => setTitleDraft(e.target.value)}
              onBlur={commitTitle}
              onKeyDown={e => { if (e.key === 'Enter') commitTitle() }}
              className="font-display text-xl text-ash bg-transparent border-b border-gold w-full focus:outline-none"
            />
          ) : (
            <h1
              className="font-display text-xl text-ash cursor-pointer hover:text-gold transition-colors"
              onClick={() => setEditingTitle(true)}
            >
              {map.title}
            </h1>
          )}
          {(map.venue || map.date) && (
            <p className="text-mist text-xs">{[map.venue, map.date].filter(Boolean).join(' · ')}</p>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* Guide me toggle */}
          {!guidedMode ? (
            <button
              onClick={enterGuidedMode}
              className="border border-gold/50 text-gold hover:bg-gold/10 px-3 py-1.5 rounded-lg text-xs transition-colors font-medium"
            >
              Guide me →
            </button>
          ) : (
            <button
              onClick={() => setGuidedMode(false)}
              className="bg-gold/20 border border-gold/50 text-gold px-3 py-1.5 rounded-lg text-xs transition-colors font-medium"
            >
              Guided mode on
            </button>
          )}

          {/* Stage toggle */}
          <div className="flex bg-flat rounded-lg p-0.5 text-xs">
            <span className="px-3 py-1.5 bg-gold text-void rounded-md font-semibold">Stage 1: Map</span>
            <Link
              to={`/map/${id}/paradigms`}
              className="px-3 py-1.5 text-mist hover:text-ash transition-colors"
            >
              Stage 2: Paradigms
            </Link>
          </div>

          {/* Export */}
          <div className="relative">
            <button
              onClick={() => setShowExport(v => !v)}
              disabled={exporting}
              className="border border-flat text-mist hover:text-ash hover:border-ash/30 px-3 py-1.5 rounded-lg text-xs transition-colors"
            >
              {exporting ? 'Exporting…' : 'Export'}
            </button>
            {showExport && (
              <div className="absolute right-0 top-full mt-1 bg-wing border border-flat rounded-lg shadow-xl z-30 overflow-hidden text-xs w-32">
                <button onClick={() => handleExport('pdf')} className="w-full text-left px-4 py-2.5 hover:bg-flat text-ash transition-colors">Save as PDF</button>
                <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2.5 hover:bg-flat text-ash transition-colors">Save as Image</button>
              </div>
            )}
          </div>

          <button
            onClick={copyLink}
            className="border border-flat text-mist hover:text-ash hover:border-ash/30 px-3 py-1.5 rounded-lg text-xs transition-colors"
          >
            {copied ? 'Copied!' : 'Share Link'}
          </button>
        </div>
      </header>

      {/* Guided mode panel */}
      {guidedMode && currentGuidedTrack ? (
        <div className="flex-1 flex flex-col overflow-hidden">
          <GuidedPanel
            track={currentGuidedTrack}
            trackIndex={guidedTrackIndex}
            totalTracks={visibleTracks.length}
            timeMarkers={map.timeMarkers}
            observations={map.observations}
            onObservationChange={updateObservation}
            onAddMarker={addTimeMarker}
            onNext={() => setGuidedTrackIndex(i => Math.min(i + 1, visibleTracks.length - 1))}
            onPrev={() => setGuidedTrackIndex(i => Math.max(i - 1, 0))}
            onExit={() => setGuidedMode(false)}
          />
        </div>
      ) : (
        <>
          {/* Hidden tracks indicator */}
          {hiddenTracks.length > 0 && (
            <div className="px-6 py-2 bg-stage border-b border-flat flex items-center gap-3 flex-wrap">
              <span className="text-mist text-xs">Hidden:</span>
              {hiddenTracks.map(t => (
                <button
                  key={t.id}
                  onClick={() => toggleTrack(t.id)}
                  className="text-xs px-2 py-0.5 rounded border transition-colors hover:bg-flat"
                  style={{ borderColor: t.color + '55', color: t.color }}
                >
                  {t.label} (show)
                </button>
              ))}
            </div>
          )}

          {/* Full map canvas */}
          <div className="flex-1 overflow-auto relative">
            <div id="map-canvas" className="min-w-max">
              {/* Column headers */}
              <div className="flex sticky top-0 z-10 bg-stage border-b border-flat">
                <div className="w-44 min-w-[11rem] border-r border-flat flex items-end px-3 py-3">
                  <span className="text-mist text-xs uppercase tracking-widest">Element</span>
                </div>
                {map.timeMarkers.map(marker => (
                  <div key={marker.id} className="min-w-[160px] w-[200px] border-r border-flat px-3 py-3 flex items-center justify-between group">
                    <span className="text-ash text-sm font-medium truncate">{marker.label}</span>
                    <button
                      onClick={() => deleteTimeMarker(marker.id)}
                      className="text-mist/30 hover:text-red-400 transition-colors text-xs opacity-0 group-hover:opacity-100 ml-1 flex-shrink-0"
                    >×</button>
                  </div>
                ))}
                <div className="px-3 py-3 flex items-center">
                  {addingMarker ? (
                    <div className="flex items-center gap-2">
                      <input
                        autoFocus
                        value={newMarkerLabel}
                        onChange={e => setNewMarkerLabel(e.target.value)}
                        onKeyDown={e => {
                          if (e.key === 'Enter') addTimeMarker()
                          if (e.key === 'Escape') { setAddingMarker(false); setNewMarkerLabel('') }
                        }}
                        placeholder="e.g. Act 1"
                        className="bg-flat border border-gold/50 rounded px-2 py-1 text-ash text-xs w-32 focus:border-gold focus:outline-none"
                      />
                      <button onClick={() => addTimeMarker()} className="text-gold text-xs hover:text-gold-dim">Add</button>
                      <button onClick={() => { setAddingMarker(false); setNewMarkerLabel('') }} className="text-mist text-xs hover:text-ash">×</button>
                    </div>
                  ) : (
                    <button
                      onClick={() => setAddingMarker(true)}
                      className="text-gold/70 hover:text-gold text-xs whitespace-nowrap transition-colors border border-dashed border-gold/30 hover:border-gold/60 px-3 py-1 rounded"
                    >
                      + Add Time Marker
                    </button>
                  )}
                </div>
              </div>

              {/* Track rows */}
              {visibleTracks.map(track => (
                <div key={track.id} className="flex border-b border-flat/50 group/row hover:bg-white/[0.01] transition-colors">
                  <div
                    className="w-44 min-w-[11rem] border-r border-flat px-3 py-3 flex items-start justify-between sticky left-0 bg-stage z-10"
                    style={{ borderLeft: `3px solid ${track.color}` }}
                  >
                    <span className="text-ash text-xs font-medium leading-snug">{track.label}</span>
                    <button
                      onClick={() => toggleTrack(track.id)}
                      className="text-mist/30 hover:text-mist text-xs opacity-0 group-hover/row:opacity-100 transition-all flex-shrink-0 ml-1"
                      title="Hide track"
                    >–</button>
                  </div>
                  {map.timeMarkers.map(marker => {
                    const key = `${track.id}:${marker.id}`
                    const obs = map.observations[key]
                    return (
                      <div key={marker.id} className="min-w-[160px] w-[200px] border-r border-flat/50 p-1">
                        <ObservationCell
                          value={obs?.content || ''}
                          onChange={val => updateObservation(track.id, marker.id, val)}
                          color={track.color}
                        />
                      </div>
                    )
                  })}
                  {map.timeMarkers.length > 0 && <div className="min-w-[200px]" />}
                </div>
              ))}

              {/* Add custom track */}
              <div className="flex border-b border-flat/30 pl-3 py-3">
                {addingTrack ? (
                  <div className="flex items-center gap-2">
                    <input
                      autoFocus
                      value={newTrackLabel}
                      onChange={e => setNewTrackLabel(e.target.value)}
                      onKeyDown={e => {
                        if (e.key === 'Enter') addTrack()
                        if (e.key === 'Escape') { setAddingTrack(false); setNewTrackLabel('') }
                      }}
                      placeholder="Custom track name…"
                      className="bg-flat border border-violet/50 rounded px-2 py-1 text-ash text-xs w-48 focus:border-violet focus:outline-none"
                    />
                    <button onClick={addTrack} className="text-violet text-xs hover:text-violet-dim">Add</button>
                    <button onClick={() => { setAddingTrack(false); setNewTrackLabel('') }} className="text-mist text-xs hover:text-ash">×</button>
                  </div>
                ) : (
                  <button
                    onClick={() => setAddingTrack(true)}
                    className="text-violet/60 hover:text-violet text-xs transition-colors border border-dashed border-violet/20 hover:border-violet/50 px-3 py-1 rounded"
                  >
                    + Add Custom Track
                  </button>
                )}
              </div>
            </div>

            {/* Empty state */}
            {map.timeMarkers.length === 0 && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="text-center">
                  <p className="text-mist text-lg font-display mb-1">Ready to map your performance</p>
                  <p className="text-mist/50 text-sm mb-4">Add time markers above, or use guided mode to be walked through each element</p>
                  <button
                    onClick={enterGuidedMode}
                    className="pointer-events-auto border border-gold/50 text-gold hover:bg-gold/10 px-5 py-2.5 rounded-lg text-sm transition-colors font-medium"
                  >
                    Start guided mode →
                  </button>
                </div>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  )
}

